#!/usr/bin/env node
/**
 * Builds `dist/packages/mcp`: the server and CLI modules, their types, and
 * `docs.json` — every package's generated `llms.txt` (the same artifacts the
 * docs site and each npm package ship, regenerated by `docs-tools:llms`) plus
 * the package catalog from the docs manifest. No bundler: the sources are
 * dependency-free ESM and are copied as they are.
 *
 * It also writes `server.json`, the entry for the official MCP registry
 * (`mcp-publisher publish`, run from the output folder after the npm
 * release). The file is generated so the version has one source — the
 * manifest — and it stays out of the npm tarball (`files`).
 */
import {
  copyFileSync,
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { PACKAGES } from '../../tools/docs-tools/lib/manifest.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..');
const out = join(root, 'dist', 'packages', 'mcp');

const manifest = JSON.parse(readFileSync(join(here, 'package.json'), 'utf8'));
const AGNOSTIC_DIRS = new Set(['core']);

const packages = [];
for (const pkg of PACKAGES) {
  // the server's own reference is about installing it, not about the suite
  if (pkg.dir === 'mcp') continue;
  const file = join(root, 'packages', pkg.dir, 'llms.txt');
  if (!existsSync(file)) continue;
  packages.push({
    npm: pkg.npm,
    label: pkg.label,
    summary: pkg.summary,
    tier: pkg.tier ?? 'mit',
    framework:
      pkg.platform === 'react'
        ? 'react'
        : pkg.platform === 'agnostic' || AGNOSTIC_DIRS.has(pkg.dir)
          ? 'agnostic'
          : 'angular',
    docsRoot: pkg.docsRoot,
    docs: readFileSync(file, 'utf8').replace(/\r\n/g, '\n'),
  });
}
if (packages.length === 0)
  throw new Error('No llms.txt found — run docs-tools:llms first.');

// Empty the folder instead of removing it: a terminal standing in it (where
// `mcp-publisher publish` runs) locks the folder itself on Windows.
mkdirSync(out, { recursive: true });
for (const entry of readdirSync(out))
  rmSync(join(out, entry), { recursive: true, force: true });
for (const file of ['src/server.mjs', 'src/cli.mjs', 'src/index.d.ts']) {
  copyFileSync(join(here, file), join(out, file.replace(/^src\//, '')));
}
for (const file of ['README.md', 'LICENSE', 'llms.txt']) {
  copyFileSync(join(here, file), join(out, file));
}
writeFileSync(
  join(out, 'package.json'),
  `${JSON.stringify(manifest, null, 2)}\n`,
);
writeFileSync(
  join(out, 'docs.json'),
  JSON.stringify({
    version: manifest.version,
    overview: readFileSync(
      join(root, 'apps', 'dev-app', 'public', 'llms.txt'),
      'utf8',
    ),
    packages,
  }),
);
const registryDescription =
  'Offline, version-exact docs for the OGE UI components (Angular and React): APIs, setup, examples.';
if (registryDescription.length > 100)
  throw new Error('server.json: the registry caps the description at 100.');
if (!manifest.mcpName)
  throw new Error('package.json: mcpName is what the registry verifies.');
writeFileSync(
  join(out, 'server.json'),
  `${JSON.stringify(
    {
      $schema:
        'https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json',
      name: manifest.mcpName,
      title: 'OGE UI',
      description: registryDescription,
      websiteUrl: 'https://www.ogeui.com',
      repository: {
        url: 'https://github.com/oge-ui/oge-ui',
        source: 'github',
        subfolder: 'packages/mcp',
      },
      version: manifest.version,
      packages: [
        {
          registryType: 'npm',
          identifier: manifest.name,
          version: manifest.version,
          transport: { type: 'stdio' },
        },
      ],
    },
    null,
    2,
  )}\n`,
);
console.log(`✓ @oge-ui/mcp: ${packages.length} packages bundled into ${out}`);
